// GH #248 fixture (ours, not a published package): JavaScript reads of a key
// a closed object lacks — a defaulted `{}` parameter (fast-string-truncated-
// width's `widthOptions = {}` then `widthOptions.regularWidth ?? 1`) and a
// local `{}` — under `??`, `||`, `?.`, destructuring defaults, `typeof` and
// `=== undefined`.
export const coalesce = (s, o = {}) => o.w ?? 1;
export const or = (s, o = {}) => o.w || 2;
export const optional = (s, o = {}) => o?.w ?? 3;
export const destructure = (s, o = {}) => { const { w = 4 } = o; return w; };
export const paramDestructure = (s, { w = 5 } = {}) => w;
export const localCoalesce = (s) => { const o = {}; return o.w ?? 6; };
export const localOr = (s) => { const o = {}; return o.w || 7; };
export const kind = (s, o = {}) => typeof o.w;
export const isUndef = (s, o = {}) => o.w === undefined;
export const isNull = (s, o = {}) => o.w === null;
export const toNull = (s, o = {}) => o.w ?? null;
export const asText = (s, o = {}) => String(o.w ?? "x");
export const arith = (s, o = {}) => { const W = o.w ?? 2; return W * 3 + (o.q ?? 0); };
export const concat = (s, o = {}) => (o.w ?? s) + "!";
export const compound = (s, o = {}) => { let n = 0; n += o.w ?? 4; return n; };
export const widths = (input, truncationOptions = {}, widthOptions = {}) => {
  const LIMIT = truncationOptions.limit ?? Infinity;
  const ELLIPSIS = truncationOptions.ellipsis ?? "";
  const TAB_WIDTH = widthOptions.tabWidth ?? 8;
  const REGULAR_WIDTH = widthOptions.regularWidth ?? 1;
  return [LIMIT, JSON.stringify(ELLIPSIS), TAB_WIDTH, REGULAR_WIDTH * input.length].join(" ");
};
